/* From Uiverse.io by ahmed150up - Tags: card */
.__UIV_SCOPE__ .card-container {
  background-color: #fff;
  border-radius: 10px;
  padding: 15px;
  margin: 20px;
  display: flex;
  flex-direction: column;
  width: 280px;
}

.__UIV_SCOPE__ .card-header {
  display: flex;
  align-items: center;
  padding-bottom: 10px;
  border-bottom: 1px solid #ccc;
}

.__UIV_SCOPE__ .card-header .img-avatar {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  margin-right: 20px;
  background-color: #333;
}

.__UIV_SCOPE__ .card-header .text-chat {
  color: black;
  margin: 0;
  font-size: 20px;
}

.__UIV_SCOPE__ .card-body {
  flex: 1;
  overflow-y: auto;
}

.__UIV_SCOPE__ .messages-container {
  padding: 15px;
}

.__UIV_SCOPE__ .message-box {
  padding: 10px;
  margin-bottom: 5px;
  border-radius: 10px;
}

.__UIV_SCOPE__ .message-box.left {
  background-color: #f1f1f1;
  color: black;
  font-size: 13px;
  left: 0;
}

.__UIV_SCOPE__ .message-box.right {
  background-color: #333;
  color: #fff;
  font-size: 13px;
  right: 0;
}

.__UIV_SCOPE__ .message-input {
  padding: 5px;
  border-top: 1px solid #ccc;
}

.__UIV_SCOPE__ .message-input .message-send {
  width: 100%;
  padding: 10px;
  border: none;
  border-radius: 10px;
  resize: none;
}

.__UIV_SCOPE__ .message-input .button-send {
  background-color: #333;
  color: #fff;
  padding: 10px 20px;
  border: none;
  cursor: pointer;
  margin-left: 10px;
  border-radius: 10px;
  font-size: 13px;
}

.__UIV_SCOPE__ .message-input .button-send:hover {
  background-color: #f1f1f1;
  color: #333;
}
